import java.util.Scanner;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] inputLine = sc.nextLine().split(" ");
        int n = Integer.parseInt(inputLine[0]);
        int mod = Integer.parseInt(inputLine[1]);

        int[] memory = new int[n + 1];
        Arrays.fill(memory, 0);
        memory[1] = 1;
        long total = 1;

        for (int i = 2; i <= n; i++) {
            int limit = (int) Math.sqrt(i) + 1;
            long sumCurr = total;

            for (int f = 2; f < limit; f++) {
                sumCurr = (sumCurr + memory[i / f]) % mod;
            }

            int boundary = i;
            for (int j = 1; j <= i / limit; j++) {
                int next_b = i / (j + 1);
                sumCurr = (sumCurr + (boundary - next_b) * (long) memory[j]) % mod;
                boundary = next_b;
            }

            total = (total + sumCurr) % mod;
            memory[i] = (int) sumCurr;
        }

        System.out.println(memory[n]);
        sc.close();
    }
}
